<template><PageHeader title="Tickets" subtitle="Create, search and track IT support requests."><button class="btn primary" @click="showForm=!showForm">+ New Ticket</button></PageHeader>
<div v-if="showForm" class="panel form-panel"><h2>Create Ticket</h2><div class="form-grid"><input v-model="newTitle" placeholder="Ticket title"><select v-model="newCategory"><option>Network</option><option>Hardware</option><option>Software</option><option>Account</option></select></div><button class="btn primary" @click="addTicket">Create Ticket</button></div>
<div class="toolbar"><input v-model="query" placeholder="Search tickets..."><select v-model="filter"><option>All</option><option>Open</option><option>Pending</option><option>Resolved</option></select></div>
<section class="panel table-wrap"><table><thead><tr><th>ID</th><th>Issue</th><th>Requester</th><th>Category</th><th>Priority</th><th>Status</th><th>Updated</th></tr></thead><tbody><tr v-for="t in filtered" :key="t.id"><td><RouterLink :to="'/tickets/'+t.id"><strong>{{t.id}}</strong></RouterLink></td><td>{{t.title}}</td><td>{{t.requester}}</td><td>{{t.category}}</td><td><span :class="['priority',t.priority.toLowerCase()]">{{t.priority}}</span></td><td><span :class="['badge',t.status.toLowerCase()]">{{t.status}}</span></td><td>{{t.updated}}</td></tr></tbody></table></section></template>
<script setup>import { ref, computed } from 'vue'; import PageHeader from '../components/PageHeader.vue'; import { tickets } from '../data/data.js'; const query=ref(''); const filter=ref('All'); const showForm=ref(false); const newTitle=ref(''); const newCategory=ref('Network'); const filtered=computed(()=>tickets.filter(t=>(filter.value==='All'||t.status===filter.value)&&(`${t.id} ${t.title} ${t.requester}`.toLowerCase().includes(query.value.toLowerCase())))); function addTicket(){if(!newTitle.value.trim())return; tickets.unshift({id:'HD-'+(1025+tickets.length),title:newTitle.value,category:newCategory.value,priority:'Medium',status:'Open',requester:'System Admin',room:'Helpdesk',updated:'just now',description:'New support request.'});newTitle.value='';showForm.value=false}</script>
